INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (1, 'Frisi 9', 'trilocale-luminoso-con-terrazzo-1', 'Trilocale luminoso con terrazzo ', 'vendita', 'Appartamento', 3, 2, 2, 86, 595000, 'Milano', 'Porta Venezia', 'Via Paolo Frisi 9', '4', 0, 'Ristrutturato', 'F', 'Autonomo', 'A Milano, nel cuore di Porta Venezia e ottimamente servita, proponiamo in vendita un luminoso trilocale disposto su due livelli, situato al quarto e quinto ( ultimo piano ) di uno stabile dotato di ascensore. L’appartamento si distingue per la sua particolare distribuzione interna, che garantisce spazi ben separati e funzionali, ideali per chi cerca una soluzione accogliente, per investimento o da personalizzare nel cuore della città.

Al primo livello troviamo un ingresso che si apre su un comodo disimpegno. Da qui si accede alla cucina abitabile, presente una prima stanza, che può essere utilizzata come camera da letto, studio o zona hobby, a seconda delle esigenze ed infine un bagno con vasca.

Salendo al secondo livello tramite una scala interna si accede alla zona giorno, caratterizzata da un luminoso soggiorno con camino decorativo, che dona un tocco di calore e raffinatezza all’ambiente. Su questo piano si trova anche la camera matrimoniale con accesso diretto a un gradevole TERRAZZINO, perfetto per godere di momenti di relax all’aperto. Completa il piano un secondo bagno finestrato con box doccia.

L’immobile è situato in un contesto urbano vivace e ben collegato: a soli cinque minuti a piedi si raggiunge la fermata della metropolitana Porta Venezia (Linea Rossa), mentre nelle immediate vicinanze si trovano diverse linee di superficie, tra cui i tram e autobus che consentono di spostarsi comodamente in tutta la città.
La zona è particolarmente apprezzata per la sua vicinanza al centro e per la presenza di numerosi servizi, tra cui supermercati, negozi di prima necessità, boutique di antiquariato, ristoranti di ogni tipo – dai locali più ricercati a quelli etnici e accessibili – che contribuiscono a rendere il quartiere dinamico e piacevole da vivere.

Questa soluzione rappresenta una scelta ideale per investimento o piccoli nuclei familiari che desiderano abitare in un appartamento unico nel suo genere, da personalizzare o pronto da vivere e in una delle zone più ambite di Milano.

Consigliata la visione.
Per maggiori informazioni e per fissare un appuntamento, non esitate a contattarci.', ARRAY['Terrazzo panoramico','Doppia esposizione','Aria condizionata','Portineria']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871632197-178a05.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871633840-b97kom.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871636234-5tlfyk.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871637229-e1tc81.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871638256-1habjs.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871640393-jhnjqg.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871641704-1h1ouu.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871643090-goqywk.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871643968-hojrvb.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871644634-stpt32.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871645745-9xgxbj.jpg']::text[], '', TRUE, TRUE, '2026-03-26', '2026-03-26T21:58:29.666055+00:00', '2026-03-26T21:58:29.666055+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (2, 'Piave', 'immobile-con-terrazzo-2', 'Immobile con Terrazzo', 'vendita', 'Villa', 6, 4, 4, 285, 1950000, 'Milano', 'Zona Indipendenza / Risorgimento', 'Viale Piave', '4', 0, 'Ottimo', 'F', 'Autonomo', 'Proponiamo la vendita della NUDA PROPRIETA'' di tre appartamenti situati in Zona Viale Piave, Milano, in una delle zone più eleganti e servite della città. Gli immobili si trovano al 3° e 4° piano di un edificio signorile con servizio di portineria tutto il giorno, doppio ingresso, doppio ascensore e riscaldamento centralizzato. La proprietà è composta da un appartamento di circa 120 mq commerciale al 4° piano, con un terrazzo di 110 mq e balcone, e da due appartamenti di 45 mq + 61 mq commerciali al 3° piano, uno con balcone. Gli immobili sono dotati di aria condizionata e due cantine di pertinenza. Grazie alla sua disposizione unica, l’immobile offre ampie possibilità di personalizzazione.
Un’opportunità unica per chi cerca una proprietà di valore in una delle zone più ricercate di Milano. 
Per maggiori informazioni e dettagli sulla nuda proprietà, non esitate a contattarci.', ARRAY['Terrazzo','Luminosità','Balcone']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871955854-3r8ae1.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871957128-yvuazu.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871957567-ehzki8.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871957998-z2an0q.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871958523-gzbmuq.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871959418-245v24.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871959677-kuswkq.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871959956-3naxlk.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871960253-253qht.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871960548-onyfy2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871982268-ttfomq.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871983836-xfcef8.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871984573-up63bn.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871985100-y84znf.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871985334-5tz55c.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871986690-7mvndr.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871987219-hpqld0.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871987496-cutjio.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774871988018-lbrwar.jpg']::text[], '', TRUE, TRUE, '2026-03-26', '2026-03-26T21:58:29.666055+00:00', '2026-03-26T21:58:29.666055+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (3, 'Liberty 20', 'bilocale-totalmente-ristrutturato-con-ampio-balcone-terrazzo-3', 'Bilocale totalmente ristrutturato con ampio balcone/terrazzo', 'affitto', 'Appartamento', 2, 1, 1, 60, 1600, 'Milano', 'Porta Venezia', 'Via Antonio Stoppani 40', '4', 2018, 'Nuovo', 'E', 'Autonomo', 'Bilocale totalmente ristrutturato con ampio balcone/terrazzo

Proponiamo in locazione splendido bilocale completamente ristrutturato, situato al quarto e penultimo piano di uno stabile ben tenuto.
L’appartamento è composto da ingresso dal terrazzo su luminoso soggiorno con cucina a vista, la zona notte è composta da una spaziosa camera da letto matrimoniale, anch’essa con accesso al proprio balcone, e da un bagno moderno dotato di box doccia.
Canone di locazione: € 1.600 / mese
Spese condominiali: € 100 / mese
Condizioni:
• pagamento mensile
• 3 mesi di deposito cauzionale
• utenze luce, gas e TARI a carico dell’inquilino
• disponibile da subito
Per maggiori informazioni o per fissare una visita non esitate a contattarci.', ARRAY['Balcone','Aria condizionata','Ascensore','Terrazzo']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872135707-8giol6.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872137056-0gktgx.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872141262-g70711.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872142657-mly0hg.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872143484-b0u1xz.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872144103-0wzywd.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872144756-gxqssk.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872145355-4epp7x.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872146264-3b7cgn.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872146821-0mu66r.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872147458-wcme9g.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872175422-xors3v.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872176859-gm0fqa.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872178419-88rch1.jpg']::text[], '', TRUE, TRUE, '2026-03-26', '2026-03-26T21:58:29.666055+00:00', '2026-03-26T21:58:29.666055+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (4, 'City Lifi-RH', 'citylife-residenza-hadid-4', 'CityLife – Residenza Hadid', 'affitto', 'Appartamento', 2, 1, 1, 112, 9160, 'Milano', 'City Life', 'Via Senofonte 4', '5', 2000, 'Nuovo', 'A', 'Centralizzato', 'Nel cuore del più esclusivo quartiere di Milano, all''interno delle iconiche residenze firmate Zaha Hadid, proponiamo in locazione un raffinato bilocale di 112 mq situato al 5° piano con ascensore, inserito in un contesto di assoluto prestigio con servizi di alto livello. L''appartamento si distingue per l''elegante zona living caratterizzata da ampie vetrate a tutta altezza che garantiscono straordinaria luminosità e una perfetta continuità tra interno ed esterno; gli spazi, curati nei minimi dettagli, sono valorizzati da arredi su misura, lampade di design e pannelli scorrevoli che separano la zona divano dalla zona pranzo, disimpegno con armadiature su misura e la cucina abitabile, separata e completamente attrezzata, ulteriore disimpegno, bagno di servizio con angolo lavanderia, cabina armadio e camera da letto che dà accesso al terrazzo, ed infine bagno principale con ulteriore accesso sul terrazzo.
Elemento distintivo della proprietà è il magnifico terrazzo angolare, sviluppato su due lati, che offre una suggestiva vista aperta a 180° sul parco CityLife e sullo skyline, incluse le iconiche torri, rappresentando uno spazio ideale per momenti di relax e convivialità all''aperto.
L''immobile presenta finiture di alto standing quali parquet, serramenti ad elevate prestazioni e impianto centralizzato con pompa di calore per il massimo comfort abitativo in ogni stagione.
La proprietà si trova all''interno di un contesto esclusivo dotato di servizio di portineria e sicurezza H24, area wellness e fitness, spazi comuni di rappresentanza, deposito biciclette e sistemi di domotica.
Canone mensile pari a € 9.160, 00 oltre spese condominiali di € 840 mensili, contratto in cedolare secca, disponibilità a partire dal 1° maggio 2026.
Per maggiori informazioni o per fissare una visita non esiti a contattarci.
Studio Arte Immobiliare.', ARRAY['Vista','Terrazzo','Area Wellness','Sicurezza 24H','Skyline']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872437517-qhn2uc.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872438933-y5pske.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872440050-ce0csu.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872440729-cc8an0.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872441451-zjp998.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872442581-tx8iem.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872443223-k16mfu.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872444249-zb5zeh.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872444801-qgetys.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872445416-8uj854.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872446091-z2lv7t.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872447321-du4ve2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872447924-9u21bk.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872448578-mmhoc2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872449055-rde84d.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872449587-smz1i8.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872450136-cpgcwj.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872451169-2qiitf.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1774872453180-lyczr6.jpg']::text[], '', TRUE, TRUE, '2026-03-26', '2026-03-26T21:58:29.666055+00:00', '2026-03-26T21:58:29.666055+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (5, 'Giga', 'trilocale-con-terrazzo-in-porta-venezia-a-milano-5', 'Trilocale con terrazzo in Porta Venezia a Milano', 'affitto', 'Appartamento', 3, 0, 2, 90, 2100, 'Milano', 'Porta Venezia', 'Via Antonio Stoppani 40', '4', -17, 'Buono', 'In corso', 'Autonomo', 'Proponiamo in locazione meraviglioso trilocale situato al quarto piano con ascensore, in un palazzo stile liberty e ben abitato, composto da ingresso su angolo cottura con zona pranzo, luminoso soggiorno con divano letto e accesso a terrazzo vivibile, camera da letto con bagno finestrato e box doccia, secondo bagno finestrato con vasca e seconda camera da letto.

Il canone richiesto è di € 2.100, 00 mensili, oltre € 200,00 di spese condominiali, comprensive di servizio di portierato full-time ( dal lunedì a venerdì e sabato mezza giornata), ascensore e gestione delle parti comuni.

Le utenze (luce, gas, internet e TARI – tassa comunale sui rifiuti da versare al Comune di Milano) sono a carico dell’inquilino.

L’immobile sarà disponibile a partire dal 1° maggio 2026.

Sono richiesti tre mesi di deposito cauzionale.

Per maggiori informazioni o per fissare una visita, restiamo a completa disposizione.', ARRAY['Terrazzo','Luminoso','Aria condizionata']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084216371-0q1dto.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084217488-ey4s8p.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084226317-byqver.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084218263-pj5wxy.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084218998-1pssxk.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084220039-q1vbrw.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084220961-ntd7c7.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084221735-kdrfot.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084222316-efufwq.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084222843-g2tca2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084223428-746pxi.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084223885-73y27p.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084224385-ni1ojq.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084224835-vch0zh.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084225590-ehzhz8.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084287759-eqy9av.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084288814-g11g32.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084289885-q6g30e.jpg']::text[], 'https://youtu.be/uM8AqJ9yp6w?si=nkmntAG6IRE_5Z69', TRUE, TRUE, '2026-04-13', '2026-04-13T12:44:57.651817+00:00', '2026-04-13T12:44:57.651817+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (6, 'Big', 'trilocale-con-due-balconi-in-porta-venezia-a-milano-6', 'Trilocale con due balconi in Porta Venezia a Milano ', 'affitto', 'Appartamento', 3, 0, 2, 90, 1800, 'Milano', 'Porta Venezia', 'Via Antonio Stoppani 40', '2', -16, 'Buono', 'In corso', 'Autonomo', 'Porta Venezia – Elegante trilocale ristrutturato con balcone e doppi servizi
In una delle zone più richieste di Milano, a pochi passi da Porta Venezia, proponiamo in locazione un raffinato appartamento situato al secondo piano di un elegante palazzo d’epoca in stile Liberty, dotato di ascensore e servizio di portineria attivo tutto il giorno.
L’immobile, recentemente ristrutturato, si presenta in ottime condizioni ed è completo di aria condizionata. Gli spazi sono ben distribuiti e luminosi, ideali per chi cerca comfort e funzionalità in un contesto signorile.

L’appartamento è così composto:
•ingresso su disimpegno
•soggiorno con angolo cottura e accesso al balcone
•due camere matrimoniali
•due bagni

Disponibile da subito

Canone di locazione agevolato:
€ 1.800/mese per i primi 2 anni + spese condominiali
€ 2.100/mese dal 3° anno + spese condominiali

Spese condominiali: € 150/mese, comprensive di ascensore, portineria, pulizia parti comuni e luce condominiale.

Utenze (luce, gas, Tari, acqua, internet) a parte.
Deposito cauzionale pari a tre mensilità.
Soluzione ideale per studenti referenziati o lavoratori.
Per maggiori informazioni o per fissare un appuntamento, restiamo a completa disposizione.', '{}'::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084364263-mj68fv.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084363317-jhyjrd.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084365388-za9xmv.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084364932-zh4use.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084359370-w62am2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084362299-02biat.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084362768-zx4gv9.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084361597-wkkoes.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084360598-fvwx37.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084366028-ozmypk.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084367593-gz5vn0.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084367068-vgdhtc.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084368506-p2duie.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084366569-wj6xv6.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084457695-sfy1tl.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084459024-02qu48.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084460069-rdn0jv.jpg']::text[], 'https://youtu.be/S4GMhU5OgVE?si=XzdnxLc6Z6rfkJ7P', TRUE, TRUE, '2026-04-13', '2026-04-13T12:48:20.706956+00:00', '2026-04-13T12:48:20.706956+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (7, 'Voghera', 'bilocale-con-2-balconi-in-porta-genova-a-milano-7', 'Bilocale con 2 balconi in Porta Genova a Milano', 'affitto', 'Appartamento', 2, 0, 1, 70, 1550, 'Via Voghera 11', 'Porta Genova', '', '5', 2000, 'Buono', 'E', 'Centralizzato', 'Proponiamo in locazione meraviglioso bilocale situato al quinto piano con ascensore, composto da ingresso su luminoso soggiorno con accesso al balcone, ampio angolo cottura, disimpegno con pratico angolo lavanderia, bagno finestrato e spaziosa camera matrimoniale con secondo balcone/terrazzino.

L’immobile è situato in zona Porta Genova, a due passi dalla metropolitana e in posizione strategica, comoda per università e principali servizi.

Il canone richiesto è di € 1.550,00 mensili, oltre € 150,00 di spese condominiali, comprensive di riscaldamento, servizio di portierato mezza giornata, ascensore e gestione delle parti comuni.

Le utenze (luce, gas, internet e TARI – tassa comunale sui rifiuti da versare al Comune di Milano) sono a carico dell’inquilino.

L’immobile sarà disponibile a partire da agosto 2026.

Sono richiesti tre mesi di deposito cauzionale.

Per maggiori informazioni o per fissare una visita, restiamo a completa disposizione.', ARRAY['2 balconi','aria condizionata','piano alto','luminoso']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084736181-uy5qr0.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084737376-9xt95l.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084736832-v2i636.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084738722-zkochz.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084737937-p77864.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084730205-ayvd4i.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084731519-11o2lx.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084732067-ng0fj4.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084732578-voypiz.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084733213-efstt1.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084733856-455b7y.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084734489-46vb13.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084735038-z0s8nc.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084735565-7wnqna.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084739588-en9hkj.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776