INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (8, 'Figini', 'bilocale-a-piano-alto-8', 'Bilocale a piano alto', 'affitto', 'Appartamento', 2, 0, 1, 55, 1300, 'Milano', 'Porta Venezia', 'Via Antonio Stoppani 40', '3', 2000, 'Buono', 'G', 'Autonomo', 'BILOCALE ARREDATO IN VIA STOPPANI, PORTA VENEZIA
Porta Venezia, Via Antonio Stoppani 40 – In una delle zone più servite e ben collegate di Milano, proponiamo in locazione un ampio appartamento arredato, situato al terzo piano con ascensore.
L''immobile si compone di: ingresso con disimpegno, ampia camera da letto, luminoso ambiente con angolo salottino, cucina abitabile di generose dimensioni utilizzabile anche come soggiorno e ampio bagno finestrato.
L''appartamento è arredato, in buone condizioni e disponibile da subito. Posizione strategica a pochi passi dai Giardini Pubblici Indro Montanelli, dalla fermata della metropolitana di Porta Venezia e da tutti i principali servizi di zona.
Si segnala che l''immobile non è dotato di aria condizionata.
Canone mensile: 1.300 euro + 100 euro di spese condominiali. Utenze (luce, gas e TARI) a carico del conduttore. Si richiedono 3 mensilità di deposito cauzionale.
Libero subito. Per maggiori informazioni, siamo a completa disposizione.', '{}'::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084937222-5xq263.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084939844-3v63pv.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084940464-9p7lsm.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084940997-8znjr9.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084935758-pksmiv.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084937706-up1kuv.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084938652-i5aukx.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084939259-kff3u3.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084941531-atbh26.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084942113-86cemd.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084942654-rdodz8.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084958341-d3mbrw.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084959600-rp4o84.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776084960885-b88j9z.jpg']::text[], 'https://youtu.be/cpvQODExVbc', FALSE, TRUE, '2026-04-13', '2026-04-13T12:56:34.523885+00:00', '2026-04-13T12:56:34.523885+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (9, 'Liberty 12', 'bilocale-con-balcone-a-milano-in-porta-venezia-9', 'Bilocale con Balcone a Milano in Porta Venezia', 'affitto', 'Appartamento', 2, 0, 1, 55, 1200, 'Milano', 'Porta Venezia', 'Via Antonio Stoppani 40', '2', -16, 'Buono', 'In corso', 'Autonomo', 'Appartamento con balcone al secondo piano con ascensore in zona Porta Venezia. L’immobile e ben rifinito, si compone di ingresso su soggiorno con cucina a vista con balcone, camera matrimoniale e bagno. L’immobile si trova a brevissima distanza da Porta Venezia e Corso Buenos Aires, in una posizione strategica che unisce la comodità del centro storico di Milano alla tranquillità di una zona residenziale ricca di servizi. Disponibile da subito. Canone mensile di 1.200 euro oltre 100 euro di spese condominiali comprensive di servizio di portineria attivo tutto il giorno, ascensore, pulizia e spese comuni, utenze a parte. Non è presente l''aria condizionata. 
Disponibile a fine Aprile 2026.
Richieste ottime referenze. Per maggiori informazioni e per organizzare una visita non esitate a contattarci', ARRAY['Balcone','No Aria Condizionata']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085155229-vjx443.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085156470-bxp10l.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085159156-y9swye.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085159688-i5ncx2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085160354-wochic.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085160853-3k8ytx.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085161548-6q19ay.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085162113-vkhycr.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085162673-nevnrj.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085157989-xq4rm5.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085158689-hl3hns.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085157234-jtoevy.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085163487-ht57ce.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085230006-vg4f7x.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776085231223-41sxv6.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776