INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (10, 'Villetta V1', 'villette-con-piscina-privata-e-vista-lago-10', 'Villette con Piscina Privata e Vista Lago!!!!', 'vendita', 'Villa', 4, 0, 2, 122, 680000, 'Gravedona ed Uniti', '', 'Località Traversa 37', '', 2026, 'Buono', 'In corso', 'Autonomo', 'Lago Como Gravedona ed Uniti – in moderno edificio con ampie vetrate PRENOTASI due eleganti villette semindipendenti con piscina privata e vista lago. 

A soli 3 km dal Lago di Como... in un’oasi di tranquillità, SOLE e luce.. nasce un edificio unico nel suo genere: una creazione architettonica dal design moderno, caratterizzata da ampie vetrate che catturano il sole durante tutto il giorno e aprono lo sguardo verso un panorama sereno e suggestivo.

L’edificio ospita due villette semindipendenti: ognuna libera su tre lati, con un giardino privato, ideale per momenti all’aperto in totale riservatezza, un posto auto esclusivo e la piscina privata 5 x 3 metri, illuminata e dotata soffione e doccia a cascata, pensata per regalare spazi di relax con vista sul paesaggio naturale circostante. 

La Disposizione interna delle Villette si sviluppa su tre livelli:
- Piano interrato: Locale tecnico con impianti piscina, ripostiglio predisposto per eventuale secondo bagno e Locale hobby versatile (palestra, sala giochi, studio, deposito attrezzature)
- Piano terra: Ampia zona giorno con grande vetrata panoramica e angolo cottura, camera matrimoniale, bagno finemente rifinito, accesso diretto al giardino e alla piscina
- Piano primo Seconda zona living con spettacolare apertura verso la vista, camera matrimoniale aggiuntiva, secondo bagno
Ogni abitazione dispone della propria piscina privata 5 x 3 metri, illuminata e dotata soffione e doccia a cascata, oltre che da un soleggiato giardino privato esposto a SUD.

Entrambe le soluzioni godono di una bella vista lago e monti, concepite con linee moderne, grandi superfici vetrate e materiali di alta qualità.

Villetta V1 - 122 mq abitazione - 210 mq di giardino privato - posto auto privato - Prezzo: € 740.000 + IVA

Villetta V2 - 122 mq abitazione  - 190 mq di giardino privato - posto auto privato - Prezzo: € 680.000 + IVA



Dotazioni tecniche e finiture previste di moderna concezione progettuale.

Ampie vetrate panoramiche che illuminano tutti gli ambienti
Impianto di climatizzazione estate/inverno con pompa di calore e split ad aria, con Bollitore in pompa di calore con accumulo da 200 litri
Pavimenti in quarzo calcestruzzo lucidato con resina protettiva antimacchia; Interni con pareti e plafoni in calcestruzzo faccia a vista trattato con protettivo
Parapetti in lamiera piena per un design pulito e contemporaneo
Pareti esterne in calcestruzzo facciavista grezzo
Travi a vista in legno e copertura isolata con rivestimento in lamiera color antracite
Rubinetteria Newform – Serie Linfa - e Sanitari Azzurra filo muro – Serie Comoda - 
Piatto doccia in resina antiscivolo con rivestimento in grandi lastre 60×120 Floris – Serie Neutra
Impianto elettrico Serie Living nera
Finiture completamente personalizzabili secondo le esigenze del cliente
Perché scegliere queste villette

A soli 3 km dal Lago di Como, con Vista aperta e privacy
Architettura moderna e materiali ricercati, con la Possibilità di personalizzare finiture e soluzioni interne
Ideali come prima casa, casa vacanza o investimento.
', ARRAY['Piscina','Giardino','Posto auto']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086860237-qhutaf.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086859531-1jpis0.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086861033-qenbyo.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086859936-n955v9.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086860648-74qygs.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086859211-qev7j9.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086857677-46u376.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086856437-8jzuaj.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086858009-bx481l.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776086858697-0jlksg.jpg']::text[], '', TRUE, TRUE, '2026-04-13', '2026-04-13T13:32:30.285452+00:00', '2026-04-13T13:32:30.285452+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (11, 'Villetta V2', 'villette-con-piscina-privata-e-vista-lago-11', 'Villette con Piscina Privata e Vista Lago!!!!', 'vendita', 'Villa', 4, 0, 2, 122, 740000, 'Gravedona ed Uniti', '', 'Località Traversa 37', '', 2026, 'Nuovo', 'In corso', 'Autonomo', 'Villette con Piscina Privata e Vista Lago!!!!

Lago di Como Gravedona ed Uniti
In posizione tranquilla e soleggiata, a soli 3 km dal lago, prenotasi due eleganti villette semindipendenti di nuova costruzione, caratterizzate da un design moderno con ampie vetrate, piscina privata e vista lago e monti.

Le villette, inserite in un edificio unico nel suo genere, sono libere su tre lati e dotate di giardino privato esposto a sud, ideale per vivere gli spazi esterni in completa privacy. Ogni unità dispone inoltre di posto auto privato e di una piscina 5×3 m illuminata, con soffione e doccia a cascata.

Distribuzione interna – 122 mq su 3 livelli

Piano interrato:
Locale tecnico piscina, ripostiglio predisposto per eventuale secondo bagno, ampio locale hobby (palestra, studio, sala giochi).

Piano terra:
Luminosissima zona giorno con grande vetrata panoramica e angolo cottura, camera matrimoniale, bagno finemente rifinito, accesso diretto al giardino e alla piscina.

Piano primo:
Seconda zona living con splendida apertura verso la vista, seconda camera matrimoniale, bagno.

Spazi esterni

• Giardino privato (210 mq V1 – 190 mq V2)
• Piscina esclusiva 5×3 m
• Esposizione solare ottimale a sud

Prezzi

• Villetta V1 – € 740.000 + IVA (122 mq + 210 mq giardino + posto auto)
• Villetta V2 – € 680.000 + IVA (122 mq + 190 mq giardino + posto auto)

Dotazioni e finiture

• Ampie vetrate panoramiche
• Impianto clima caldo/freddo con pompa di calore – bollitore 200 lt
• Pavimenti in quarzo-calcestruzzo con resina protettiva
• Interni in calcestruzzo faccia a vista trattato
• Parapetti in lamiera piena dal design contemporaneo
• Copertura isolata con travi a vista e finitura in lamiera antracite
• Rubinetteria Newform serie Linfa – Sanitari Azzurra serie Comoda
• Piatto doccia in resina antiscivolo + rivestimento lastre 60×120 Floris
• Impianto elettrico Serie Living nero
• Finiture personalizzabili su richiesta

Perché sceglierle

• Modernità e privacy a pochi minuti dal lago
• Vista aperta su lago e montagne
• Spazi luminosi grazie alle grandi vetrate
• Piscina privata e giardino esposto a sud
• Perfette come prima casa, casa vacanza o investimento.', '{}'::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087552089-cyjyr2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087550631-vugv7v.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087551639-9w44uz.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087552448-0flvxw.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087552848-jd5sl4.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087553209-63cchv.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087571560-12056z.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087572572-54a3jy.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087573153-077jaa.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1776087574019-ta3wjy.jpg']::text[], '', TRUE, TRUE, '2026-04-13', '2026-04-13T13:39:47.943872+00:00', '2026-04-13T13:39:47.943872+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (13, 'VillaLomazzo', 'elegate-villa-con-parco-di-2-000mq-e-piscina-nuda-proprieta-13', 'ELEGATE VILLA CON PARCO DI 2.000MQ E PISCINA-NUDA PROPRIETA''', 'vendita', 'Villa', 2, 4, 4, 447, 550000, 'Lomazzo', '', 'Via Ceresio', 'Terra', 1980, 'Buono', 'G', 'Autonomo', 'Proponiamo in vendita la nuda proprietà di un’elegante villa immersa nella quiete di un magnifico parco privato di circa 2.000 mq, una proprietà di rara reperibilità nel comune di Lomazzo.
La residenza, realizzata negli anni ’80, si sviluppa su circa 250 mq distribuiti su due livelli e offre ambienti ampi, luminosi e armoniosamente integrati con il verde circostante, grazie alle grandi vetrate che regalano splendide viste sul giardino e sulla piscina.
Il vero protagonista della proprietà è il parco: un autentico angolo di natura, impreziosito da alberi secolari e da una vegetazione rigogliosa che assicura privacy assoluta, silenzio e un’atmosfera di pace in ogni stagione.
La splendida piscina interrata si inserisce perfettamente nel paesaggio, creando una naturale continuità tra gli spazi interni ed esterni e trasformando la villa in un luogo ideale dove vivere momenti di relax e convivialità.
Realizzata con le caratteristiche delle prestigiose abitazioni dell’epoca, la villa conserva il fascino delle costruzioni degli anni ’80, con ambienti generosi, soffitti importanti e una distribuzione degli spazi studiata per garantire comfort e funzionalità.

La posizione è particolarmente strategica: Lomazzo, a pochi minuti dall’ingresso autostradale, consente di raggiungere comodamente Milano, Como e il confine svizzero, coniugando la tranquillità di un contesto riservato con la comodità dei principali collegamenti.
Una residenza dove natura, privacy ed eleganza si fondono in perfetto equilibrio, rappresentando un’opportunità unica per chi desidera investire in un immobile destinato a conservare il proprio valore nel tempo
Per maggiori informazioni o per organizzare una visita, saremo lieti di accompagnarvi alla scoperta di questa esclusiva proprietà.', ARRAY['giardino privato','piscina']::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797218822-onbk1d.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797198954-0cc8u2.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797203361-khbfsc.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797205464-x5rfs8.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797207346-a2ti7y.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797214196-pbilx7.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797201623-5sk7d1.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797209204-oea5vz.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797211130-g4rcfb.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797216957-1jysid.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797220926-46dpm6.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797222808-pmbwcq.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797224762-iigusk.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797226780-yh0y0g.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797229318-frqq5a.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797229774-kt6g0y.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797231962-h598wx.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797233929-grd1hm.PNG','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797235636-8wuui4.PNG']::text[], '', FALSE, TRUE, '2026-07-23', '2026-07-23T09:03:47.411972+00:00', '2026-07-23T09:03:47.411972+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (15, 'Vallarsa/FondazionePrada', 'bilocale-ristrutturato-in-vendita-in-fondazione-prada-15', 'BILOCALE RISTRUTTURATO IN VENDITA IN FONDAZIONE PRADA', 'vendita', 'Appartamento', 2, 0, 1, 55, 340000, 'Milano', 'Fondazione Prada', 'Via Vallarsa 22', '', 2000, 'Ristrutturato', 'G', 'Autonomo', 'A pochi passi dalla Fondazione Prada e nelle immediate vicinanze di Porta Romana, proponiamo in vendita uno splendido bilocale di 52 mq, ristrutturato e disponibile da subito.
L’immobile, situato al primo piano alto di un contesto tranquillo e ben abitato, si compone di ingresso, luminoso soggiorno con angolo cottura, valorizzato da doppie finestre e da una splendida doppia esposizione a Sud ed Est, ampia camera matrimoniale con ripostiglio in quota e bagno completamente nuovo, mai utilizzato.
Completa la proprietà una cantina di 7 mq, particolarmente spaziosa. Riscaldamento autonomo e spese condominiali contenute, pari a circa 700 € annui.

La posizione è uno dei punti di forza: la zona della Fondazione Prada, grazie alla vicinanza dello Scalo Romana, del futuro Villaggio Olimpico, dell’Università Bocconi e della metropolitana, è oggi una delle aree più richieste e in maggiore rivalutazione di Milano.

Soluzione ideale sia come prima casa sia come investimento, grazie all’elevata richiesta di locazioni.

Le immagini arredate presenti nell’annuncio sono render fotorealistici realizzati a scopo illustrativo per mostrare una possibile soluzione di arredo. L’immobile viene venduto completamente vuoto.

Per maggiori informazioni o per fissare una visita, non esitate a contattarci.
Studio Arte Immobiliare.', '{}'::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797691504-7w8bwy.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797691988-ppdjxj.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797692448-q3ztwx.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797692937-fgfns4.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797693359-6x8xsd.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797693982-mw46n6.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797694761-jmkcju.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797696391-e63km5.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797696805-6u55sl.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797694345-ahicn1.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797690863-iockc7.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784797689559-9yskt9.jpg']::text[], '', FALSE, TRUE, '2026-07-23', '2026-07-23T09:13:19.884299+00:00', '2026-07-23T09:13:19.884299+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (16, 'PLINIO', 'milano-via-plinio-14-16', 'MILANO – VIA PLINIO 14', 'affitto', 'Appartamento', 3, 0, 1, 75, 2000, 'Milano', 'Porta Venzia', 'Via Plinio 14', '3', 2000, 'Buono', 'F', 'Centralizzato', 'A pochi passi dalla fermata MM1 Lima e da Corso Buenos Aires, in una delle zone più richieste e servite di Milano, proponiamo in locazione un ampio appartamento situato al terzo piano di un elegante stabile signorile con ascensore.

L’immobile gode di una piacevole vista aperta sul verde dei giardini circostanti, una caratteristica rara e particolarmente apprezzata in una posizione così centrale.

L’appartamento si sviluppa con una distribuzione degli spazi funzionale e luminosa. L’ingresso si apre su un comodo disimpegno che conduce ai diversi ambienti della casa. La cucina è abitabile e dotata di balcone. L’originario soggiorno è stato trasformato in una spaziosa camera matrimoniale con un pratico angolo living. Completano la proprietà altre due camere matrimoniali di generose dimensioni, una delle quali dispone di un secondo balcone, oltre a un bagno finestrato e ad ulteriori spazi di disimpegno.

L’immobile è dotato di aria condizionata ed è una soluzione ideale per studenti e giovani professionisti. La posizione è particolarmente strategica per raggiungere in pochi minuti il Politecnico di Milano, l’Istituto Marangoni, l’Università degli Studi di Milano e altri importanti istituti universitari della città, grazie agli ottimi collegamenti con la metropolitana e i mezzi pubblici. La zona offre inoltre supermercati, negozi, ristoranti, bar e tutti i principali servizi comodamente raggiungibili a piedi.
Canone di locazione: € 2.000/mese.
Spese condominiali: € 150/mese, comprensive di riscaldamento centralizzato, ascensore e servizi condominiali.
Disponibile da subito.
Per maggiori informazioni o per fissare una visita, contattate Studio Arte Immobiliare.', '{}'::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798108100-fpxm08.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798108701-4oucij.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798109345-9q60xe.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798110067-pb8qut.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798110501-cm5sc3.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798110949-jfjik2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798111505-tm4pf9.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798111987-qa20uh.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798112753-mjc8d8.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798113349-7na5gh.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798113965-kau18m.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798115769-nq4rbj.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798116544-cobatn.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798117213-cvbx4f.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798119554-kserfu.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798118500-kqheeo.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798117778-pcvnhl.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798114396-7aejdr.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798115255-dhdx77.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798114791-jk3oz1.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798119985-zd7mfx.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798107016-cu5yyz.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798120437-hsmhc2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1784798120900-zr1cui.jpg']::text[], '', FALSE, FALSE, '2026-07-23', '2026-07-23T09:17:45.507095+00:00', '2026-07-23T09:17:45.507095+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (17, 'Sidoli', 'trilocale-ampio-in-palazzo-d-epoca-citta-studi-via-sidoli-19-milano-17', 'Trilocale ampio in palazzo d''epoca – Città Studi, Via Sidoli 19, Milano', 'affitto', 'Appartamento', 3, 2, 1, 83, 1460, 'Milano', 'Città Studi - Susa', 'Via Sidoli 19', '1', 1919, 'Buono', 'G', 'Centralizzato', 'Trilocale ampio in palazzo d''epoca – Città Studi, Via Sidoli 19, Milano

Nel cuore di Città Studi, in un elegante e prestigioso palazzo storico, proponiamo in affitto un luminoso appartamento di 83 mq commerciali, situato al primo piano di uno stabile senza ascensore. L''immobile si sviluppa con ingresso su disimpegno, due camere matrimoniali, soggiorno con angolo cottura e bagno, offrendo una soluzione comoda e ben proporzionata, ideale per studenti, funzionale e ben collegato.

La posizione è tra le più richieste e servite di Milano, a pochi passi dalle principali università, prima fra tutte il Politecnico di Milano, e comodissima ai mezzi: la fermata della metropolitana Susa si raggiunge in appena cinque minuti a piedi. Ottimo anche il collegamento con il Passante Ferroviario, con la stazione di Dateo praticamente dietro l''angolo.
L''appartamento è disponibile dal 1° settembre.

Il canone di locazione richiesto è di 1.460 euro al mese, a cui si aggiungono 180 euro di spese condominiali che comprendono il riscaldamento, il servizio di portineria (attivo a mezza giornata) e tutte le spese relative alla gestione del palazzo, salvo conguaglio. Il pagamento è previsto con cadenza trimestrale ed è richiesta una cauzione pari a tre mensilità. Si segnala che all''interno dello stabile non è disponibile un posto per le biciclette e moto.

Per maggiori informazioni e per fissare una visita, non esitate a contattarci.
Studio Arte Immobiliare.', '{}'::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178954284-lo9pno.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178955639-5pj17f.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178956163-69lih1.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178956783-y2dclu.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178957499-jv2bxa.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178958019-ndlb5x.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178958675-gfe0nd.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178959420-8peuyj.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178960591-78eno2.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178961117-grqct0.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178962068-qs1n4g.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178962469-kgneix.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178962934-kd2mzy.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178961592-ebla74.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178959897-agglov.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178963360-k7nqa9.HEIC','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178965251-k9ym6g.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787178966691-6rkdqz.HEIC']::text[], '', FALSE, TRUE, '2026-08-19', '2026-08-19T22:37:25.149928+00:00', '2026-08-19T22:37:25.149928+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (18, 'Liberty 13', 'porta-venezia-trilocale-ultimo-piano-luminosissimo-18', 'PORTA VENEZIA | TRILOCALE ULTIMO PIANO – LUMINOSISSIMO', 'affitto', 'Appartamento', 3, 2, 2, 90, 2000, 'Milano', 'Porta Venezia', 'Via Antonio Stoppani 40', '5', 1919, 'Ristrutturato', 'E', 'Autonomo', 'Proponiamo in affitto un ampio trilocale situato all’ultimo piano di un elegante palazzo in stile Liberty, caratterizzato da spazi generosi e da una luminosità eccezionale. La distribuzione interna prevede ingresso su ampio disimpegno, soggiorno con cucina a vista, due ampie camere matrimoniali e due bagni finestrati con box doccia.
L’appartamento è disponibile da subito, con un canone mensile di € 2.000 + € 150 di spese e deposito cauzionale pari a tre mensilità. Si precisa che non è presente l’aria condizionata.
La posizione è strategica e particolarmente apprezzata da studenti e giovani professionisti. L’appartamento è ottimamente collegato ai mezzi pubblici e permette di raggiungere facilmente il Politecnico di Milano, Istituto Marangoni, Università degli Studi di Milano, la Bocconi e le principali università della città. Inoltre, la fermata della metropolitana M4 Dateo, raggiungibile in circa 10 minuti a piedi, consente collegamenti rapidi con il centro di Milano, l’Aeroporto di Linate e le principali zone della città.
La zona offre inoltre supermercati, negozi, ristoranti, bar e tutti i principali servizi raggiungibili comodamente a piedi.
Per maggiori informazioni o per fissare una visita non esitate a contattarci.', '{}'::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179238279-pghvqt.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179220497-9j1yz7.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179233550-6eyna5.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179230919-mk8uzz.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179231338-i197vd.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179230473-0rud90.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179231865-6sll27.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179227514-wm5e6k.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179226738-aojw9h.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179228606-ephp7n.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179229165-e517el.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179229531-nsmv3n.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179230095-kwbzue.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179343509-v9v5km.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179344863-scqmy9.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179345814-m3q8gf.jpg']::text[], 'https://youtu.be/P3PP1Kh7jms?si=bN2aOIvpVrHjdsyA', FALSE, TRUE, '2026-08-19', '2026-08-19T22:43:09.132301+00:00', '2026-08-19T22:43:09.132301+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.immobili (id, codice, slug, titolo, tipo, categoria, locali, camere, bagni, mq, prezzo, citta, zona, indirizzo, piano, anno, stato, classe_energetica, riscaldamento, descrizione, caratteristiche, immagini, video_url, evidenza, pubblicato, data_inserimento, created_at, updated_at) VALUES (19, 'Anna', 'bilocale-in-porta-venezia-19', 'BILOCALE IN PORTA VENEZIA', 'affitto', 'Appartamento', 2, 1, 1, 55, 1400, 'Milano', 'Porta Venezia', 'Via Antonio Stoppani 40', '1', 1919, 'Ristrutturato', 'E', 'Autonomo', 'Proponiamo a Milano all''interno di un palazzo in stile Liberty di inizio 900, bilocale COMPLETAMENTE RISTRUTTURATO situato al primo piano con ascensore, servizio di portineria tutto il giorno e completamente arredato.
L’appartamento è cosi composto: ingresso su soggiorno con cucina completa, camera matrimoniale ed infine bagno con box doccia. Il canone mensile richiesto è di € 1.400 più €100 di spese condominiali che coprono il servizio portineria tutto il giorno, illuminazione dello stabile, pulizia condominiale, ascensore, Wi-fi. Presente pinguino per raffredamento ambiente come "aria condizionata", utenze a parte, riscaldamento autonomo.
L''immobile si trova in una zona ben servita dai mezzi pubblici, in particolare dalla metropolitana Porta Venezia situata a 13 minuti a piedi, dal passante ferroviario e da vari mezzi di superficie. L''area è caratterizzata dalla sua vicinanza al centro e per la presenza di molteplici negozi di ogni genere, da quelli di prima necessità ai negozi di antiquariato, ai ristoranti ricercati e raffinati a quelli etnici e più’ a portata di mano.
RICHIESTE OTTIME REFERENZE.
CONSIGLIABILE LA VISIONE!
Disponibile da subito.
Per maggiori informazioni e visite non esitate a contattarci.', '{}'::text[], ARRAY['https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179526050-yr5hmh.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179526562-jzd4fa.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179524681-nv41xu.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179525158-b4sfva.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179525638-p4qqxq.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179522074-c0mdoq.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179523316-5yo6ev.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179524111-ogtwud.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179565649-h6naoq.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179566788-do2fsu.jpg','https://efldhensgxzvgawgxzwz.supabase.co/storage/v1/object/public/foto-immobili/immobili/1787179567677-o446en.jpg']::text[], '', FALSE, FALSE, '2026-08-19', '2026-08-19T22:46:24.73789+00:00', '2026-08-19T22:46:24.73789+00:00') ON CONFLICT (id) DO NOTHING;
